@asynccontextmanager
async def _request(
    self, method: str, url: str, *,
    auth: YandexAuth | None,
    params=None, json=None,
    not_found: YandexTrackerError | None = None,
    conflict: YandexTrackerError | None = None,
) -> AsyncIterator[ClientResponse]:
    try:
        async with self._session.request(
            method, url,
            headers=await self._build_headers(auth),
            params=params, json=json,
        ) as response:
            if not_found and response.status == 404:
                raise not_found
            if conflict and response.status == 409:
                raise conflict
            await self._raise_for_status(response)
            yield response
    except TimeoutError as exc:
        raise TrackerAPITimeout(
            method=method, url=url, timeout=self._timeout
        ) from exc

# каждый метод:
async def issue_get(self, issue_id, *, auth=None) -> Issue:
    async with self._request(
        "GET", f"v3/issues/{issue_id}", auth=auth,
        not_found=IssueNotFound(issue_id),
    ) as response:
        return Issue.model_validate_json(await response.read())

class _TimeoutAwareSession:
    """ClientSession, у которой таймаут говорит, что именно истекло."""

    def __init__(self, session: ClientSession, timeout: float):
        self._session, self._timeout = session, timeout

    def get(self, url, **kw):    return self._ctx("GET", url, kw)
    def post(self, url, **kw):   return self._ctx("POST", url, kw)
    def patch(self, url, **kw):  return self._ctx("PATCH", url, kw)
    def delete(self, url, **kw): return self._ctx("DELETE", url, kw)

    @asynccontextmanager
    async def _ctx(self, method, url, kw):
        try:
            async with self._session.request(method, url, **kw) as r:
                yield r          # таймаут в response.read() прилетит сюда
        except TimeoutError as exc:
            raise TrackerAPITimeout(
                method=method, url=url, timeout=self._timeout
            ) from exc

